const cwd="/home/axel/LeanAlgebraicGeometry-Horizon";
const cmds=[
 `rg -n 'commutatorPairingRestriction_surjective_of_divisible' FormalizedSources/AbelianVarieties/Mumford/blueprint FormalizedSources/AbelianVarieties/Mumford/hgraph || true`,
 `find FormalizedSources/AbelianVarieties/Mumford/hgraph -type f | wc -l`,
 `rg -l '\\\\notready' FormalizedSources/AbelianVarieties/Mumford/blueprint/src | wc -l`,
 `rg -n '\\\\leanok' FormalizedSources/AbelianVarieties/Mumford/blueprint/src | wc -l`,
 `git --git-dir="$HORIZON_LEDGER_GIT_DIR" --work-tree="$HORIZON_LEDGER_WORK_TREE" status --short --untracked-files=all | head -30`
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:cwd,max_output_tokens:3000})));
rs.forEach((r,i)=>text(`---${i}---\n${r.output}`));
